import { Dropdown, DropdownPopover, DropdownTrigger } from "../../base/dropdown/dropdown";
import { InputBase, TextField } from "../../base/input/input";
import { RadioDot } from "../../base/radio/radio";
import { VerticalScroll } from "../../base/scroll-area/vertical-scroll";
import { EffortControl } from "../../base/slider/effort-control";
import { cx } from "@/lib/cx";
import type { ComposerModel } from "./composer";

export interface ModelProvider {
  id: string;
  label: string;
  icon?: ComponentType<{ className?: string }>;
  models: readonly ComposerModel[];
}
export interface ModelPickerProps {
  providers: readonly ModelProvider[];
  value: string;
  onChange: (model: string) => void;
  effort: number;
  onEffortChange: (effort: number) => void;
  className?: string;
}
const EFFORT_LABELS = ["Low", "Medium", "Balanced", "High", "Very High", "Max"];

/** Provider browsing and cross-provider model search with a nested effort control. */
export function ModelPicker({ providers, value, onChange, effort, onEffortChange, className }: ModelPickerProps) {
  const selectedProvider = providers.find(provider => provider.models.some(model => model.id === value));
  const selectedModel = selectedProvider?.models.find(model => model.id === value);
  const [isOpen, setOpen] = useState(false);
  const [providerId, setProviderId] = useState(selectedProvider?.id ?? providers[0]?.id);
  const [searching, setSearching] = useState(false);
  const [query, setQuery] = useState("");
  const scrollRef = useRef<HTMLDivElement>(null);
  const providerRefs = useRef(new Map<string, HTMLButtonElement>());
  const focusFrame = useRef<number | null>(null);
  const activeProvider = providers.find(provider => provider.id === providerId) ?? selectedProvider ?? providers[0];
  const selectedProviderId = selectedProvider?.id;
  const selectedEffort = Number.isFinite(effort) ? Math.max(0, Math.min(5, Math.round(effort))) : 1;
  useEffect(() => { if (selectedProviderId) setProviderId(selectedProviderId); }, [selectedProviderId]);
  useEffect(() => { if (scrollRef.current) scrollRef.current.scrollTop = 0; }, [activeProvider?.id, query, searching]);
  useEffect(() => () => { if (focusFrame.current !== null) cancelAnimationFrame(focusFrame.current); }, []);
  const closeSearch = () => {
    setQuery("");
    setSearching(false);
    if (focusFrame.current !== null) cancelAnimationFrame(focusFrame.current);
    focusFrame.current = requestAnimationFrame(() => {
      focusFrame.current = null;
      const first = providers[0];
      if (first) providerRefs.current.get(first.id)?.focus();
    });
  };
  useEffect(() => {
    if (!isOpen) return;
    const handleKey = (event: KeyboardEvent) => {
      const target = event.target instanceof Element ? event.target : null;
      if (target?.closest('[role="dialog"][aria-label="Effort"]')) return;
      if (event.key === "Escape" && searching) {
        event.preventDefault();
        event.stopImmediatePropagation();
        if (query) setQuery("");
        else closeSearch();
      } else if (event.key === "/" && !target?.closest('input,textarea,[contenteditable="true"]')) {
        event.preventDefault();
        event.stopImmediatePropagation();
        setSearching(true);
      }
    };
    document.addEventListener("keydown", handleKey, true);
    return () => document.removeEventListener("keydown", handleKey, true);
  });
  const results = searching
    ? providers.flatMap(provider => provider.models
      .filter(model => `${provider.label} ${model.label}`.toLowerCase().includes(query.trim().toLowerCase()))
      .map(model => ({ provider, model })))
    : (activeProvider?.models ?? []).map(model => ({ provider: activeProvider!, model }));
  return <Dropdown isOpen={isOpen} onOpenChange={next => {
    setOpen(next);
    if (!next) { setSearching(false); setQuery(""); }
  }}>
    <DropdownTrigger aria-label={`Select model: ${selectedModel?.label ?? "Select model"}`}
      isDisabled={!providers.some(provider => provider.models.length)}
      className={cx("flex h-8 shrink-0 items-center justify-center gap-0.5 rounded-xl bg-background-primary-default py-1.5 pe-1 ps-2 outline-none transition-colors duration-150 ease hover:bg-background-primary-hover", className)}>
      <span className="px-0.5 text-body-medium whitespace-nowrap text-text-secondary">{selectedModel?.label ?? "Select model"}</span>
      <RiArrowDownSLine aria-hidden className={cx("size-[18px] shrink-0 text-foreground-icon-secondary transition-transform duration-200 ease", isOpen && "rotate-180")} />
    </DropdownTrigger>
    <DropdownPopover aria-label="Models" placement="top start" offset={8}
      className="relative h-[282px] w-[341px] overflow-clip rounded-[20px] p-0 shadow-model-picker"
      dialogClassName="block size-full">
      <div role="tablist" aria-label="Providers" aria-orientation="vertical"
        className="absolute top-0.5 start-0.5 h-[276px] w-[42px] overflow-y-auto rounded-[17px] bg-composer-panel-rail-background p-[3px] [scrollbar-width:none]">
        <div className="flex w-9 flex-col gap-1.5">
          {providers.map(provider => {
            const Icon = provider.icon ?? RiCpuLine;
            return <Button key={provider.id} unstyled role="tab" aria-selected={activeProvider?.id === provider.id}
              aria-label={provider.label} title={provider.label}
              ref={element => { if (element) providerRefs.current.set(provider.id, element); else providerRefs.current.delete(provider.id); }}
              onClick={() => { setProviderId(provider.id); setSearching(false); setQuery(""); }}
              className={cx("flex h-[30px] w-9 shrink-0 cursor-pointer items-center justify-center rounded-[50px] outline-none transition-colors duration-150 ease focus-visible:ring-2 focus-visible:ring-border-focus-ring", activeProvider?.id === provider.id ? "bg-background-tertiary-default" : "hover:bg-background-tertiary-default/50")}>
              <Icon className="size-5 shrink-0 text-foreground-icon-secondary" />
            </Button>;
          })}
        </div>
      </div>
      <div className="absolute top-2 end-2 bottom-0 start-[52px] flex flex-col">
        <div className="flex h-5 items-center justify-between gap-[5px] px-0.5">
          {searching ? <>
            <TextField aria-label="Search models" value={query} onChange={setQuery} className="min-w-0 flex-1">
              <InputBase autoFocus placeholder="Search models"
                fieldClassName="rounded-none bg-transparent p-0 ring-0 focus-within:ring-0 shadow-none"
                className="h-5 pl-0 text-body-medium caret-accent-500 focus:placeholder:text-text-tertiary" />
            </TextField>
            <Button unstyled aria-label="Close search" onClick={closeSearch}
              className="flex shrink-0 cursor-pointer items-center rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring">
              <RiSearchLine aria-hidden className="size-4 shrink-0 text-foreground-icon-secondary" />
            </Button>
          </> : <>
            <span className="text-body-medium text-text-tertiary">Models</span>
            <Button unstyled aria-label="Quick search" onClick={() => setSearching(true)}
              className="flex shrink-0 cursor-pointer items-center gap-[5px] rounded-sm opacity-50 outline-none transition-opacity duration-150 hover:opacity-100 focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-border-focus-ring">
              <span className="text-body-medium whitespace-nowrap text-text-secondary">Quick Search</span>
              <RiSearchLine aria-hidden className="size-4 shrink-0 text-foreground-icon-secondary" />
            </Button>
          </>}
        </div>
        <VerticalScroll variant="model-picker" scrollRef={scrollRef} role="radiogroup" tabIndex={-1}
          aria-label={searching ? "Matching models" : `${activeProvider?.label ?? "Available"} models`}
          className="mt-1 flex min-h-0 flex-1 flex-col" scrollClassName="flex min-h-0 flex-1 flex-col gap-1 pb-1">
          {results.map(({ provider, model }) => {
            const checked = value === model.id;
            const Icon = provider.icon ?? RiCpuLine;
            return <div key={`${provider.id}:${model.id}`}
              className={cx("relative flex h-9 w-full shrink-0 items-center gap-3 rounded-2lg px-2 transition-colors duration-150", checked ? "bg-background-primary-hover" : "hover:bg-background-primary-hover")}>
              <Button unstyled role="radio" aria-checked={checked} aria-label={`${provider.label} ${model.label}`}
                onClick={() => { onChange(model.id); if (searching) { setProviderId(provider.id); setSearching(false); setQuery(""); } }}
                className="absolute inset-0 cursor-pointer rounded-2lg outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-border-focus-ring" />
              <span className="pointer-events-none flex min-w-0 flex-1 items-center gap-3">
                <span className="flex min-w-0 flex-1 items-center gap-1.5">
                  <Icon className="size-4 shrink-0 text-foreground-icon-secondary" />
                  <span className="min-w-0 flex-1 truncate text-body-medium whitespace-nowrap"><span className="text-text-primary">{model.label}</span>{searching && <span className="ms-1.5 text-text-tertiary">{provider.label}</span>}</span>
                  {checked && <EffortPicker value={selectedEffort} onChange={onEffortChange} />}
                </span>
              </span>
              <RadioDot selected={checked} size="sm" className="pointer-events-none" />
            </div>;
          })}
          {!results.length && <p className="px-2 py-2 text-body-medium text-text-tertiary">No models match</p>}
        </VerticalScroll>
      </div>
    </DropdownPopover>
  </Dropdown>;
}
function EffortPicker({ value, onChange }: { value: number; onChange: (value: number) => void }) {
  const [isOpen, setOpen] = useState(false);
  return <Dropdown isOpen={isOpen} onOpenChange={setOpen}>
    <DropdownTrigger aria-label={`Effort: ${EFFORT_LABELS[value]}`}
      className="pointer-events-auto relative flex shrink-0 cursor-pointer items-center rounded-full bg-background-tertiary-default py-1 pe-1 ps-2 outline-none transition-colors duration-150 ease hover:bg-background-tertiary-hover focus-visible:ring-2 focus-visible:ring-border-focus-ring">
      <span className="text-body-2-medium whitespace-nowrap text-text-secondary">{EFFORT_LABELS[value]}</span><RiArrowDownSLine aria-hidden className={cx("size-[18px] shrink-0 text-foreground-icon-secondary transition-transform duration-200 ease", isOpen ? "rotate-90" : "-rotate-90")} />
    </DropdownTrigger>
    <DropdownPopover aria-label="Effort" placement="bottom start" offset={8} className="w-[266px] p-1"
      dialogClassName="gap-0 pt-1">
      <EffortControl presentation="popover" value={value} onChange={onChange} />
    </DropdownPopover>
  </Dropdown>;
}

