/** Permission selection shared by compact and panel composers. */
export function PermissionMenu({ value, onChange, label, learnMoreHref, onLearnMore }: PermissionMenuProps) {
  const [permissionOpen, setPermissionOpen] = useState(false);
  const selectedPermission = value;
  const permissionMode = PERMISSION_MODES.find((mode) => mode.id === value) ?? PERMISSION_MODES[0];
  const permissionText = label ?? permissionMode.label;
  const PermissionIcon = permissionMode.Icon;
  return (
    <Dropdown isOpen={permissionOpen} onOpenChange={setPermissionOpen}>
      <DropdownTrigger
        aria-label={`Permission: ${permissionText}`}
        className={cx(
          "flex h-[30px] shrink-0 items-center gap-1 rounded-full py-[5px] pe-2.5 ps-2 outline-none transition-colors duration-150 ease hover:bg-background-primary-hover data-[pressed]:bg-background-primary-hover data-[focus-visible]:bg-background-primary-hover",
          permissionOpen && "bg-background-primary-hover",
        )}
      >
        <PermissionIcon
          className={cx(
            "size-4 shrink-0 text-foreground-icon-secondary",
            (selectedPermission === "manual" || selectedPermission === "plan") && "-scale-y-100",
          )}
        />
        <span className="text-body-medium whitespace-nowrap text-text-secondary">
          {permissionText}
        </span>
      </DropdownTrigger>
      <DropdownPopover
        aria-label="Permissions"
        placement="top start"
        offset={8}
        className="w-[323px] rounded-[20px] p-1.5"
        dialogClassName="gap-1.5 pt-1"
      >
        <div className="flex items-center gap-2.5 px-2 text-body-medium text-text-tertiary">
          <span className="min-w-0 flex-1">Permissions</span>
          <LinkButton
            {...(learnMoreHref ? { href: learnMoreHref } : {})}
            onClick={onLearnMore}
            variant="secondary"
            className="shrink-0 text-text-tertiary"
          >
            Learn more
          </LinkButton>
        </div>
        <div role="radiogroup" aria-label="Permission mode" className="flex flex-col gap-1">
          {PERMISSION_MODES.map(({ id, label, description, Icon }) => (
            <Button
              key={id}
              unstyled
              role="radio"
              aria-checked={id === selectedPermission}
              onClick={() => {
                onChange(id);
                setPermissionOpen(false);
              }}
              className={cx(
                "flex w-full cursor-pointer items-center gap-2 rounded-[14px] p-2 text-start outline-none transition-colors",
                id === selectedPermission
                  ? "bg-background-primary-hover"
                  : "hover:bg-background-primary-hover focus-visible:bg-background-primary-hover",
              )}
            >
              <Icon
                className={cx(
                  "size-5 shrink-0 text-foreground-icon-secondary",
                  (id === "manual" || id === "plan") && "-scale-y-100",
                )}
              />
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-body-medium text-text-secondary">{label}</span>
                <span className="truncate text-body-2-medium text-text-tertiary">
                  {description}
                </span>
              </span>
            </Button>
          ))}
        </div>
      </DropdownPopover>
    </Dropdown>
  );
}

"use client";
import {
  RiCheckLine,
  RiFileCopyLine,
  RiRefreshLine,
  RiThumbDownLine,
  RiThumbUpLine,
} from "@remixicon/react";
import { useState } from "react";
import { IconButton } from "../../base/buttons/icon-button";
export function ConversationFeedback({
  text,
  onRetry,
  retryDisabled = false,
  variant = "default",
  showRetry = true,
}: {
  variant?: "default" | "subtle" | "compact";
  showRetry?: boolean;
  text: string;
  onRetry: () => void;
  retryDisabled?: boolean;
}) {
  const [vote, setVote] = useState<"up" | "down" | null>(null);
  const [copied, setCopied] = useState(false);
  const subtle = variant === "subtle";
  const compact = variant === "compact";
  const style = compact
    ? "flex size-[22px] items-center justify-center rounded-md bg-background-tertiary-default text-foreground-icon-tertiary outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring [&_svg]:size-3"
    : subtle
      ? "group flex cursor-pointer items-center rounded-lg bg-background-tertiary-default p-1.5 text-foreground-icon-secondary transition-colors duration-150 ease hover:bg-background-secondary-hover hover:text-foreground-icon-primary"
      : undefined;
  return (
    <div className="flex items-center gap-1 text-text-tertiary">
      <IconButton
        unstyled={subtle || compact}
        className={style}
        size="small"
        icon={vote === "up" ? RiCheckLine : RiThumbUpLine}
        aria-label={subtle ? "Good response" : "Helpful response"}
        aria-pressed={vote === "up"}
        onClick={() => setVote((value) => (value === "up" ? null : "up"))}
      />
      <IconButton
        unstyled={subtle || compact}
        className={style}
        size="small"
        icon={RiThumbDownLine}
        aria-label={subtle ? "Bad response" : "Unhelpful response"}
        aria-pressed={vote === "down"}
        onClick={() => setVote((value) => (value === "down" ? null : "down"))}
      />
      <IconButton
        unstyled={subtle || compact}
        className={style}
        size="small"
        icon={copied ? RiCheckLine : RiFileCopyLine}
        aria-label={copied ? "Copied response" : "Copy response"}
        onClick={async () => {
          try {
            await navigator.clipboard.writeText(text);
            setCopied(true);
          } catch {
            setCopied(false);
          }
        }}
      />
      {showRetry && (
        <IconButton
          size="small"
          icon={RiRefreshLine}
          aria-label="Regenerate response"
          disabled={retryDisabled}
          onClick={onRetry}
        />
      )}
    </div>
  );
}

