  const [messages, setMessages] = useState<AIChatMessage[]>(
    initialMessages ??
      (autoRun && !onSend ? [{ id: "prompt", role: "user", content: PROMPT }] : []),
  );
  const [phase, setPhase] = useState<
    "idle" | "working" | "finishing" | "done" | "stopped" | "error"
  >(autoRun && !initialMessages && !onSend ? "working" : "idle");
  const [run, setRun] = useState(0);
  const [error, setError] = useState("");
  const controller = useRef<AbortController | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const generation = useRef(0);
  const reduced = useReducedMotion();
  const busy = phase === "working";
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    setMounted(false);
    if (!busy || onSend) return;
    const id = setTimeout(() => setMounted(true), 1000);
    return () => clearTimeout(id);
  }, [busy, onSend, run]);
  const clear = () => {
    generation.current += 1;
    controller.current?.abort();
    if (timer.current) clearTimeout(timer.current);
  };
  useEffect(
    () => () => {
      controller.current?.abort();
      if (timer.current) clearTimeout(timer.current);
    },
    [],
  );
  useEffect(() => {
    if (!busy || onSend) return;
    const timeout = setTimeout(() => setPhase("finishing"), 18100);
    timer.current = timeout;
    return () => clearTimeout(timeout);
  }, [busy, onSend, run]);
  useEffect(() => {
    if (phase !== "finishing") return;
    const timeout = setTimeout(() => {
      setMessages((old) => [...old, { id: `answer-${run}`, role: "assistant", content: SUMMARY }]);
      setPhase("done");
    }, 300);
    timer.current = timeout;
    return () => clearTimeout(timeout);
  }, [phase, run]);
  const send = async (value: string, retryHistory?: AIChatMessage[]) => {
    const prompt = value.trim();
    if (!prompt) return;
    clear();
    const requestId = generation.current;
    const abort = new AbortController();
    controller.current = abort;
    const history = retryHistory ?? [
      ...messages,
      { id: `user-${requestId}`, role: "user" as const, content: prompt },
    ];
    setMessages(history);
    setInput("");
    setError("");
    setPhase("working");
    setRun(requestId);
    if (onSend) {
      try {
        const content = await onSend(prompt, { signal: abort.signal, messages: history });
        if (generation.current !== requestId || abort.signal.aborted) return;
        setMessages((old) => [...old, { id: `answer-${requestId}`, role: "assistant", content }]);
        setPhase("done");
      } catch (cause) {
        if (generation.current !== requestId || abort.signal.aborted) return;
        setError(cause instanceof Error ? cause.message : "The response could not be completed.");
        setPhase("error");
      }
    }
  };
  const retry = (responseId?: string) => {
    const responseIndex = responseId
      ? messages.findIndex((item) => item.id === responseId)
      : messages.length;
    const history = messages.slice(0, responseIndex);
    const userIndex = history.findLastIndex((item) => item.role === "user");
    if (userIndex >= 0) void send(history[userIndex].content, history.slice(0, userIndex + 1));
  };
  return (
    <AgentWorkspace
      navigationActions={!!onSend}
      {...workspace}
      kind="chat"
      input={input}
      onInputChange={setInput}
      onSubmit={(value) => void send(value)}
      onStop={() => {
        clear();
        setPhase("stopped");
      }}
      onNew={() => {
        clear();
        setMessages([]);
        setInput("");
        setError("");
        setPhase("idle");
      }}
      busy={onSend ? busy : false}
      thinking={busy && (onSend ? true : mounted)}
      contained={contained}
      className={className}
      panel={
        onSend ? (
          <p className="p-3 text-body-regular text-text-secondary">
            No file changes reported by this agent.
          </p>
        ) : (
          <>
            <p className="sr-only">Example file changes</p>
            <AgentChangesPanel
              enableBrowserPreview={enableBrowserPreview}
              filePath={workspace?.codeFilePath}
            />
          </>
        )
      }
    >
      {messages.length === 0 && (
        <div className="flex flex-1 flex-col justify-center py-20 text-center">
          <h1 className="text-title-2-medium text-text-primary">What would you like to build?</h1>
          <p className="pt-2 text-body-regular text-text-secondary">
            Start a conversation with your coding agent.
          </p>
        </div>
      )}
      {messages.map((message) => (
        <motion.div
          key={message.id}
          initial={run === 0 || reduced ? false : { opacity: 0, y: 8, filter: "blur(3px)" }}
          animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
          transition={{ duration: reduced ? 0 : 0.4, ease: [0.22, 1, 0.36, 1] }}
          className={cx(
            "text-body-regular text-text-primary",
            message.role === "user"
              ? workspaceUserMessageClasses
              : "w-full whitespace-pre-line",
          )}
        >
          <p>{message.content}</p>
          {message.role === "assistant" && (
            <div className="mt-2">
              {!onSend && <ExampleChangeSnippet />}
              <ConversationFeedback
                text={message.content}
                variant={onSend ? "default" : "subtle"}
                showRetry={!!onSend}
                onRetry={() => retry(message.id)}
                retryDisabled={busy}
              />
            </div>
          )}
        </motion.div>
      ))}
      <AnimatePresence>
        {busy && (
          <motion.div
            key={`run-${run}`}
            initial={run === 0 || reduced ? false : { opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.3 }}
            className="flex flex-col gap-3"
          >
            {onSend && (
              <p role="status" className="text-body-2-regular text-text-tertiary">
                Waiting for your agent…
              </p>
            )}
            {!onSend && mounted && (
              <AgentProgress
                stepDuration={3000}
                steps={[
                  "Read project files",
                  "Update and install light mode tokens",
                  "Implement dark mode tokens",
                  "Add reusable registered theme toggle",
                  "Run registry, lint and production build",
                ]}
              />
            )}
          </motion.div>
        )}
      </AnimatePresence>
      {phase === "stopped" && (
        <p role="status" className="text-body-regular text-text-secondary">
          Response stopped.
        </p>
      )}
      {phase === "error" && (
        <p role="alert" className="text-body-regular text-status-rose-text">
          {error}
        </p>
      )}
      {(phase === "stopped" || phase === "error") && (
        <Button size="small" variant="secondary" className="self-start" onClick={() => retry()}>
          Retry response
        </Button>
      )}
    </AgentWorkspace>
  );
}

"use client";
import { motion } from "motion/react";
import { type ReactNode, type Ref } from "react";
import { Button } from "../../base/buttons/button";
import { cx } from "@/lib/cx";

/** Shared compact navigation reveal, measured from the rendered preview. */
export const TEMPLATE_NAVIGATION_TRANSITION = { duration: 0.325, ease: "easeInOut" } as const;

export interface TemplateContentFrameProps {
  children: ReactNode;
  variant?: "dashboard" | "workspace";
  className?: string;
  navigationOpen?: boolean;
  onCloseNavigation?: () => void;
  closeRef?: Ref<HTMLButtonElement>;
  contained?: boolean;
  columnClassName?: string;
}

/** Page content scrolls inside the viewport on compact screens and inside contained previews. */
export function TemplateContentFrame({
  children,
  variant = "dashboard",
  className,
  navigationOpen = false,
  onCloseNavigation,
  closeRef,
  contained,
  columnClassName,
}: TemplateContentFrameProps) {
  return (
    <motion.main
      initial={false}
      animate={{ x: navigationOpen ? 272 : 0, borderRadius: navigationOpen ? 32 : 0 }}
      transition={TEMPLATE_NAVIGATION_TRANSITION}
      className={cx(
        "relative z-20 flex min-h-0 min-w-0 flex-1 justify-center overflow-x-hidden overflow-y-auto bg-background-full p-3 will-change-transform sm:pt-6 lg:z-0 lg:transform-none! lg:rounded-none!",
        !contained && variant !== "workspace" && "lg:overflow-visible",
        variant === "workspace" &&
          "flex-col justify-start gap-2 overflow-hidden p-0 sm:pt-0 lg:overflow-hidden",
        className,
      )}
    >
      <motion.div
        initial={false}
        animate={{ opacity: navigationOpen ? 1 : 0 }}
        transition={TEMPLATE_NAVIGATION_TRANSITION}
        className={cx(
          "absolute inset-0 z-50 rounded-[inherit] lg:hidden",
          !navigationOpen && "pointer-events-none",
        )}
      >
        <Button
          unstyled
          type="button"
          ref={closeRef}
          aria-label="Close navigation"
          tabIndex={navigationOpen ? 0 : -1}
          onClick={onCloseNavigation}
          className="absolute inset-0 cursor-pointer rounded-[inherit] bg-black/10 dark:bg-white/5"
        />
      </motion.div>
      <div
        data-template-content=""
        inert={navigationOpen || undefined}
        className={cx(
          variant === "workspace"
            ? "flex min-h-0 min-w-0 flex-1 gap-3 overflow-hidden"
            : "flex w-full max-w-[1300px] flex-col gap-2.5",
          columnClassName,
        )}
      >
        {children}
      </div>
    </motion.main>
  );
}

"use client";
import { RiGroupLine, RiMenuLine } from "@remixicon/react";
import { motion } from "motion/react";
import { type ComponentProps, type ReactNode, type Ref, useEffect, useRef, useState } from "react";
import { IconButton } from "../../base/buttons/icon-button";
import { cx } from "@/lib/cx";
import {
  DASHBOARD_NAV,
  DashboardSidebar,
  type DashboardNavItem,
} from "../dashboard/dashboard-sidebar";
import { type DashboardAccount } from "../dashboard/dashboard-identity";
import { TemplateContentFrame, TEMPLATE_NAVIGATION_TRANSITION } from "./template-content-frame";
import { TemplateTopBar, type TemplateTopBarProps } from "./template-top-bar";

export interface TemplateShellProps
  extends Omit<
    TemplateTopBarProps,
    "navigationOpen" | "onOpenNavigation" | "navigationTriggerRef"
  > {
  variant?: "dashboard" | "workspace";
  navigationBreakpoint?: "md" | "lg";
  sidebarOptions?: Pick<
    NonNullable<ComponentProps<typeof DashboardSidebar>>,
    "header" | "className" | "showThemeToggle" | "settings"
  >;
  workspaceHeader?: (controls: {
    onOpenNavigation: () => void;
    navigationOpen: boolean;
    navigationTriggerRef: Ref<HTMLButtonElement>;
  }) => ReactNode;
  teamFooter?: NonNullable<ComponentProps<typeof DashboardSidebar>>["teamFooter"];
  navigation?: NonNullable<ComponentProps<typeof DashboardSidebar>>["navigation"];
  panel?: ReactNode;
  resizer?: ReactNode;
  overlays?: ReactNode;
  selected?: string;
  children: ReactNode;
  contained?: boolean;
  className?: string;
  columnClassName?: string;
  hideHeader?: boolean;
  navigationPlacement?: "row" | "overlay";
  frameClassName?: string;
  navigationItems?: DashboardNavItem[];
  accounts?: DashboardAccount[];
}

const TEMPLATE_NAV = [
  ...DASHBOARD_NAV,
  { key: "hr", label: "HR Team", icon: RiGroupLine, href: "/templates/hr" },
];

/** Templates compose this navigation, top bar and content frame; page bodies only own their content. */
export function TemplateShell({
  variant = "dashboard",
  navigationBreakpoint = "lg",
  navigation,
  sidebarOptions,
  workspaceHeader,
  teamFooter,
  panel,
  resizer,
  overlays,
  selected = "home",
  children,
  contained,
  className,
  columnClassName,
  hideHeader,
  navigationPlacement = "row",
  frameClassName,
  navigationItems = TEMPLATE_NAV,
  accounts,
  ...topBar
}: TemplateShellProps) {
  const [navOpen, setNavOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  const restoreFocus = useRef(false);
  useEffect(() => {
    if (!navOpen && restoreFocus.current) {
      restoreFocus.current = false;
      triggerRef.current?.focus();
    }
  }, [navOpen]);
  const closeNavigation = () => {
    restoreFocus.current = true;
    setNavOpen(false);
  };
  useEffect(() => {
    if (!navOpen) return;
    closeRef.current?.focus();
    const escape = (event: KeyboardEvent) => {
      if (event.key === "Escape" && !event.defaultPrevented) {
        restoreFocus.current = true;
        setNavOpen(false);
      }
    };
    window.addEventListener("keydown", escape);
    const desktop = window.matchMedia(
      navigationBreakpoint === "md" ? "(min-width:768px)" : "(min-width:1024px)",
    );
    const resized = () => {
      if (desktop.matches) setNavOpen(false);
    };
    desktop.addEventListener("change", resized);
    return () => {
      window.removeEventListener("keydown", escape);
      desktop.removeEventListener("change", resized);
    };
  }, [navOpen, navigationBreakpoint]);
  const sidebarProps = {
    ...sidebarOptions,
    items: navigationItems,
    navigation,
    teamFooter,
    selected,
    account: topBar.account,
    accounts,
    team: topBar.team,
  };
  return (
    <div
      className={cx(
        "relative flex w-full bg-background-full max-lg:overflow-hidden",
        contained ? "h-full min-h-[600px] overflow-hidden" : "h-dvh lg:h-auto lg:min-h-screen",
        variant === "workspace" && "gap-4 overflow-hidden p-3 lg:h-dvh lg:min-h-0",
        className,
      )}
    >
      {overlays}
      <div
        className={cx(
          "sticky top-3 z-10 hidden shrink-0 py-0 pl-3",
          navigationBreakpoint === "md" ? "md:block" : "lg:block",
          contained ? "my-3 h-[calc(100%-24px)]" : "h-[calc(100dvh-24px)]",
          variant === "workspace" && "static h-full p-0 my-0",
        )}
      >
        <DashboardSidebar {...sidebarProps} />
      </div>
      <div
        data-template-navigation="compact"
        aria-hidden={!navOpen}
        inert={!navOpen || undefined}
        className={cx(
          "start-0 z-10 flex w-[272px] py-3 ps-[6px]",
          navigationBreakpoint === "md" ? "md:hidden" : "lg:hidden",
          contained ? "absolute inset-y-0" : "fixed inset-y-0",
        )}
      >
        <motion.div
          initial={false}
          animate={{ opacity: navOpen ? 1 : 0, scale: navOpen ? 1 : 0.94 }}
          transition={TEMPLATE_NAVIGATION_TRANSITION}
          className="h-full w-[260px] origin-left will-change-transform rtl:origin-right"
        >
          <DashboardSidebar {...sidebarProps} mobile flat onClose={closeNavigation} />
        </motion.div>
      </div>
      <TemplateContentFrame
        variant={variant}
        className={frameClassName}
        navigationOpen={navOpen}
        onCloseNavigation={closeNavigation}
        closeRef={closeRef}
        contained={contained}
        columnClassName={columnClassName}
      >
        {variant === "workspace" ? (
          <div className="relative flex min-w-0 flex-1 basis-0">
            <section className="relative flex h-full min-w-0 flex-1 flex-col overflow-hidden rounded-3xl bg-background-secondary-default">
              {workspaceHeader ? (
                workspaceHeader({
                  onOpenNavigation: () => setNavOpen(true),
                  navigationOpen: navOpen,
                  navigationTriggerRef: triggerRef,
                })
              ) : (
                <TemplateTopBar
                  {...topBar}
                  variant="workspace"
                  navigationOpen={navOpen}
                  onOpenNavigation={() => setNavOpen(true)}
                  navigationTriggerRef={triggerRef}
                />
              )}
              {children}
            </section>
            {resizer}
          </div>
        ) : hideHeader && navigationPlacement === "overlay" ? null : hideHeader ? (
          <div className="lg:hidden">
            <IconButton
              ref={triggerRef}
              icon={RiMenuLine}
              aria-label="Open navigation"
              aria-expanded={navOpen}
              onClick={() => setNavOpen(true)}
            />
          </div>
        ) : (
          <TemplateTopBar
            {...topBar}
            navigationOpen={navOpen}
            onOpenNavigation={() => setNavOpen(true)}
            navigationTriggerRef={triggerRef}
          />
        )}
        {variant === "workspace" ? (
          panel
        ) : hideHeader && navigationPlacement === "overlay" ? (
          <div className="relative flex w-full flex-col gap-4 [&>*]:shrink-0">
            <IconButton
              ref={triggerRef}
              icon={RiMenuLine}
              aria-label="Open navigation"
              aria-expanded={navOpen}
              onClick={() => setNavOpen(true)}
              className="absolute top-3 start-3 z-10 rounded-full lg:hidden"
            />
            {children}
          </div>
        ) : (
          children
        )}
      </TemplateContentFrame>
    </div>
  );
}

